glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec2 b = floor(uv * vec2(48.0 * uRatio, 48.0));
  float t = floor(uTime * 20.0);
  float on = step(1.0 - uAmount * 0.25, hash(b + t * 1.3));
  vec3 n = vec3(hash(b + t), hash(b + t + 1.0), hash(b + t + 2.0));
  return vec4(mix(c.rgb, n, on), c.a);
}
